const GENERATION_ROW_PREFIX=256;const GENERATION_LIMITS={runRows:1e4};async function lockPostgresGeneration(e,t){const n=await e.query(`SELECT c.relname AS name, c.relkind AS kind, pg_get_userbyid(c.relowner) AS owner
     FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
     WHERE n.nspname=$1 AND c.relkind IN ('r','p','m','S') ORDER BY c.relname COLLATE "C"`,[t]);const r=n.rows.filter(({kind:e})=>e===`r`||e===`p`);if(r.length)await e.query(`LOCK TABLE ${r.map(({name:e})=>`${quoteSqliteIdentifier(t)}.${quoteSqliteIdentifier(e)}`).join(`,`)} IN ACCESS EXCLUSIVE MODE`);for(const{name:r,kind:i,owner:a}of n.rows)if(i===`S`||i===`m`)await e.query(`ALTER ${i===`S`?`SEQUENCE`:`MATERIALIZED VIEW`} ${quoteSqliteIdentifier(t)}.${quoteSqliteIdentifier(r)} OWNER TO ${quoteSqliteIdentifier(a)}`)}async function inspectPostgresGeneration(e,t,n=GENERATION_LIMITS){const r=await e.query(`SELECT m.store, m.version::text AS version, m.store_id,
     n.nspowner=(SELECT oid FROM pg_roles WHERE rolname=current_user) AS owned
     FROM ${quoteSqliteIdentifier(t.namespace)}.openclaw_schema_meta m
     CROSS JOIN pg_namespace n WHERE n.nspname=$1`,[t.namespace]);const i=r.rows[0];if(r.rows.length!==1||!i?.owned||i.store_id!==t.storeId||!Number.isSafeInteger(Number(i.version))||Number(i.version)<0)throw new Error(`PostgreSQL anchor does not match its owned generation metadata`);await e.query(`SELECT set_config('search_path',$1,true)`,[quoteSqliteIdentifier(t.namespace)]);const a=readPostgresCatalog(JSON.parse((await e.query(`SELECT catalog::text FROM (${postgresCatalogQuery(t.namespace,true)}) generation`)).rows[0].catalog)).filter(e=>e.kind!==`functionDefinition`);const o=await e.query(`SELECT p.oid::regprocedure::text AS name, pg_get_functiondef(p.oid) AS definition
     FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
     WHERE n.nspname=$1 AND p.prokind IN ('f','p','w')`,[t.namespace]);for(const{name:e,definition:t}of o.rows)a.push({table:e,kind:`functionDefinition`,value:t});const s={};const c=await e.query(`SELECT c.relname AS name, coalesce(p.remote, false) OR coalesce(p.bytes, pg_table_size(c.oid))
       < coalesce($2::bigint, pg_size_bytes(current_setting('work_mem')) / 4) AS whole
     FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
     LEFT JOIN LATERAL (SELECT sum(pg_table_size(l.relid)) AS bytes, bool_or(r.relkind='f') AS remote
       FROM pg_partition_tree(c.oid) l JOIN pg_class r ON r.oid=l.relid) p ON true
     WHERE n.nspname=$1 AND c.relkind IN ('r','p','m') ORDER BY c.relname COLLATE "C"`,[t.namespace,n.wholeSortBytes??null]);for(const{name:r,whole:i}of c.rows){const a=createHash(`sha256`);const o=`${quoteSqliteIdentifier(t.namespace)}.${quoteSqliteIdentifier(r)}`;let c=0;const stream=async(t,n,r=[])=>{let i=0;await e.query(`DECLARE ${t} NO SCROLL CURSOR FOR ${n}`,r);try{for(;;){const n=await e.query(`FETCH FORWARD 128 FROM ${t}`);for(const e of n.rows){a.update(e.row).update(`
`);i++}if(n.rows.length<128)break}}finally{await e.query(`CLOSE ${t}`)}c+=i;return i};if(i){await stream(`openclaw_generation_rows`,`SELECT row_to_json(t)::text AS row FROM ${o} t ORDER BY row_to_json(t)::text COLLATE "C"`);s[r]={rows:c,sha256:a.digest(`hex`)};continue}let l=[];let u=[];let d;const hashRuns=async()=>{if(!l.length)return;const t=await e.query(`SELECT s.value AS row FROM (SELECT row_to_json(t)::text COLLATE "C" AS value FROM ${o} t
         WHERE t.ctid = ANY($1::tid[]) AND t.tableoid::int8::text || ':' || t.ctid::text = ANY($2::text[])) s
         ORDER BY s.value`,[u,l]);if(t.rows.length!==l.length)throw new Error(`PostgreSQL generation changed during inspection`);for(const e of t.rows){a.update(e.row).update(`
`);c++}l=[];u=[]};const closeRun=async e=>{if(e.rows<=n.runRows){l=l.concat(e.keys);u=u.concat(e.tids);if(l.length>=128)await hashRuns();return}await hashRuns();if(await stream(`openclaw_generation_run`,`SELECT row_to_json(t)::text AS row FROM ${o} t
         WHERE left(row_to_json(t)::text, ${GENERATION_ROW_PREFIX}) COLLATE "C" = $1
         ORDER BY row_to_json(t)::text COLLATE "C"`,[e.prefix])!==e.rows)throw new Error(`PostgreSQL generation changed during inspection`)};await e.query(`DECLARE openclaw_generation_rows NO SCROLL CURSOR FOR SELECT t.tableoid::int8::text || ':' || t.ctid::text AS key,
       t.ctid::text AS tid, left(row_to_json(t)::text, ${GENERATION_ROW_PREFIX}) COLLATE "C" AS prefix FROM ${o} t ORDER BY prefix`);try{for(;;){const t=await e.query(`FETCH FORWARD 128 FROM openclaw_generation_rows`);for(const e of t.rows){if(d?.prefix!==e.prefix){if(d)await closeRun(d);d={prefix:e.prefix,rows:0,keys:[],tids:[]}}if(++d.rows<=n.runRows){d.keys.push(e.key);d.tids.push(e.tid)}else if(d.keys.length){d.keys=[];d.tids=[]}}if(t.rows.length<128)break}if(d)await closeRun(d);await hashRuns()}finally{await e.query(`CLOSE openclaw_generation_rows`)}s[r]={rows:c,sha256:a.digest(`hex`)}}const l=await e.query(`SELECT c.relname AS name, s.seqstart::text AS start, s.seqincrement::text AS increment,
     s.seqmin::text AS minimum, s.seqmax::text AS maximum, s.seqcache::text AS cache, s.seqcycle AS cycle
     FROM pg_sequence s JOIN pg_class c ON c.oid=s.seqrelid JOIN pg_namespace n ON n.oid=c.relnamespace
     WHERE n.nspname=$1 ORDER BY c.relname COLLATE "C"`,[t.namespace]);const u={};for(const{name:n,...r}of l.rows){a.push({table:n,kind:`sequenceDefinition`,value:r});u[n]=(await e.query(`SELECT last_value::text AS value, is_called AS called FROM ${quoteSqliteIdentifier(t.namespace)}.${quoteSqliteIdentifier(n)}`)).rows[0]}a.sort((e,t)=>{const n=JSON.stringify(e),r=JSON.stringify(t);return n<r?-1:n>r?1:0});return{store:i.store,version:Number(i.version),catalog:a,tables:s,allocations:u}}function fingerprintPostgresGeneration(e,t){return createHash(`sha256`).update(JSON.stringify({engine:`postgres`,namespace:e.namespace,storeId:e.storeId,...t})).digest(`hex`)}export{inspectPostgresGeneration as n,lockPostgresGeneration as r,fingerprintPostgresGeneration as t};